// Iron Banners — more conquests: Napoleon 1805–1812 and Genghis Khan 1206–1222.
'use strict';

// ---------- Napoleonic units
unit('conscript', { name: 'Conscript Infantry', cls: 'inf', era: 3, atk: 12, def: 10, mor: 55, tags: ['volley'], pen: 6, br: 3.7, hidden: true, note: 'Young men of the annual class, called up early and trained on the march.' });
unit('oldline',   { name: 'Prussian Line Infantry', cls: 'inf', era: 3, atk: 12, def: 11, mor: 60, tags: ['volley'], pen: 6, br: 3.7, hidden: true, note: 'Drilled in the rigid linear tactics of Frederick the Great, fifty years out of date by 1806.' });
unit('russline',  { name: 'Russian Infantry', cls: 'inf', era: 3, atk: 13, def: 14, mor: 80, tags: ['discipline', 'volley'], pen: 6, br: 4.0, hidden: true, note: 'Serf conscripts serving 25 years. Poorly trained in skirmishing, famously hard to break.' });
unit('militia',   { name: 'Militia', cls: 'inf', era: 3, atk: 7, def: 8, mor: 45, pen: 4, br: 2.7, hidden: true, note: 'Landwehr, opolchenie and Spanish levies: brave, untrained, often armed with pikes.' });
unit('cossack',   { name: 'Cossacks', cls: 'lcav', era: 3, atk: 8, def: 5, mor: 65, tags: ['feint'], br: 3.0, hidden: true, note: 'Irregular horsemen from the Don: useless against a square, deadly to stragglers and foragers.' });
unit('lancer',    { name: 'Polish Lancers', cls: 'lcav', era: 3, atk: 14, def: 8, mor: 85, tags: ['shock', 'feint'], br: 4.0, hidden: true, note: 'The Polish light horse of the Imperial Guard, who charged up the pass at Somosierra.' });

// ---------- Mongol-era units
unit('mongolha', { name: 'Mongol Horse Archers', cls: 'lcav', era: 2, atk: 10, def: 6, mor: 85, tags: ['feint', 'volley'], br: 3.3, hidden: true, note: 'Each man rode with four or five remounts and carried two bows and 60 arrows. Units of ten, a hundred and a thousand moved on signals from flags and drums.' });
unit('mongollancer', { name: 'Mongol Heavy Cavalry', cls: 'hcav', era: 2, atk: 12, def: 9, mor: 85, tags: ['shock'], br: 3.0, hidden: true, note: 'Lancers in lamellar armor on armored horses, sent in once the horse archers had broken the enemy ranks.' });
unit('keshig',    { name: 'The Keshig', cls: 'hcav', era: 2, atk: 13, def: 10, mor: 95, tags: ['shock', 'discipline'], br: 3.3, hidden: true, note: 'The Khan\'s 10,000-man bodyguard, drawn from the sons of commanders — hostages and an officer school at once.' });
unit('trebuchet', { name: 'Siege Engineers', cls: 'art', era: 2, atk: 12, def: 3, mor: 60, br: 2.7, hidden: true, note: 'Chinese and later Persian engineers with traction trebuchets, crossbow artillery and naphtha pots.' });
unit('jininf',    { name: 'Jin Infantry', cls: 'inf', era: 2, atk: 6, def: 7, mor: 50, br: 2.0, hidden: true, note: 'Han Chinese and Khitan foot soldiers, many of them conscripts of doubtful loyalty to their Jurchen rulers.' });
unit('jurchen',   { name: 'Jurchen Heavy Cavalry', cls: 'hcav', era: 2, atk: 11, def: 9, mor: 70, tags: ['shock'], br: 3.0, hidden: true, note: 'The armored horsemen who had conquered north China a century earlier.' });
unit('ghulam',    { name: 'Turkic Ghulams', cls: 'hcav', era: 2, atk: 11, def: 9, mor: 75, tags: ['shock'], br: 3.0, hidden: true, note: 'Slave-soldier cavalry of the Khwarazm Shah, mostly Kipchak and Kangli Turks.' });
unit('citymil',   { name: 'City Militia', cls: 'pike', era: 2, atk: 4, def: 6, mor: 45, br: 1.3, hidden: true, note: 'Townsmen defending their walls.' });

